import test from "node:test";import assert from "node:assert/strict";import {readConfig} from "../src/config.js";import {createLogger} from "../src/logger.js";import {sha256} from "../src/security/hash.js";import {ExecutionTier,validateStrategySignal,validateThesis,validateRiskConfig,validatePortfolioState,validateOrder,validateReconciliation} from "../src/contracts/index.js";test("configuration defaults to paper",()=>{const c=readConfig({});assert.equal(c.tradingMode,"paper");assert.equal(c.liveEnabled,false);assert.throws(()=>{c.tradingMode="live";},TypeError);});test("invalid configuration rejected",()=>assert.throws(()=>readConfig({TRADING_MODE:"unsafe"})));test("logger emits JSON",()=>{const lines=[];const sink={info:x=>lines.push(x),log:()=>{},warn:()=>{},error:()=>{}};createLogger({sink}).info("hello",{component:"test"});assert.equal(JSON.parse(lines[0]).message,"hello");});test("hash deterministic",()=>{assert.equal(sha256("trading-nova"),sha256("trading-nova"));assert.notEqual(sha256("a"),sha256("b"));});test("signal validates score/probability",()=>{assert.doesNotThrow(()=>validateStrategySignal({strategyId:"demo",strategyVersion:"1",symbol:"BTCUSDT",direction:"long",opportunityScore:83,probability:.67}));assert.throws(()=>validateStrategySignal({strategyId:"demo",strategyVersion:"1",symbol:"BTCUSDT",direction:"long",opportunityScore:101}));});test("thesis requires evidence and invalidation",()=>{assert.doesNotThrow(()=>validateThesis({thesisId:"t1",statement:"trend",invalidation:"support break",evidence:["e1"]}));assert.throws(()=>validateThesis({thesisId:"t1",statement:"x",invalidation:"y",evidence:[]}));});test("risk config requires positive limits",()=>{assert.doesNotThrow(()=>validateRiskConfig({version:"risk-1",configHash:sha256("approved"),maxPositionNotional:100,maxDailyLoss:10,maxDrawdown:20}));assert.throws(()=>validateRiskConfig({version:"risk-1",configHash:"",maxPositionNotional:100,maxDailyLoss:10,maxDrawdown:20}));});test("portfolio state validates before risk limits",()=>{assert.doesNotThrow(()=>validatePortfolioState({equity:1000,dailyPnl:-10,drawdown:1}));assert.throws(()=>validatePortfolioState({equity:-1,dailyPnl:0,drawdown:0}));});test("order requires execution tier",()=>{assert.doesNotThrow(()=>validateOrder({orderId:"o1",symbol:"BTCUSDT",side:"buy",quantity:1,tier:ExecutionTier.PAPER}));assert.throws(()=>validateOrder({orderId:"o1",symbol:"BTCUSDT",side:"buy",quantity:1,tier:"unknown"}));});test("reconciliation blocks mismatch",()=>{assert.doesNotThrow(()=>validateReconciliation({status:"matched"}));assert.throws(()=>validateReconciliation({status:"mismatch"}));});